fn backtrack<'a>(
    sub_words: &[&'a str],
    whole_word: &str,
    nk: usize,
    start: usize,
    current: &mut BTreeSet<&'a str>,
    result: &mut HashSet<BTreeSet<&'a str>>,
) {
    if current.len() == nk {
        if is_anagram(whole_word, &current.iter().copied().collect::<String>()) {
            result.insert(current.clone());
        }
        return;
    }
    for i in start..sub_words.len() {
        current.insert(sub_words[i]);
        backtrack(sub_words, whole_word, nk, i + 1, current, result);
        current.remove(sub_words[i]);
        backtrack(sub_words, whole_word, nk, i + 1, current, result);
    }
}

pub fn anagram_combos(sub_words: &[&str], whole_word: &str) -> usize {
    let mut result = HashSet::new();
    backtrack(
        sub_words,
        whole_word,
        whole_word.len() / sub_words.first().unwrap().len(),
        0,
        &mut BTreeSet::new(),
        &mut result,
    );
    result.len()
}

