use std::collections::HashMap;

fn back_track(
    index: usize,
    magazine: &[&str],
    accumulated_letters: &mut HashMap<char, i32>,
    mut min_cost: Option<i32>,
    dict_letters_word: &HashMap<char, i32>,
) -> Option<i32> {
    if index == magazine.len() {
        // ??? MISSING LINE ???
        for (letter, quantity) in dict_letters_word.iter() {
            if !accumulated_letters.contains_key(letter) || *quantity > accumulated_letters[letter]
            {
                return min_cost;
            } else {
                cost = Some(cost.unwrap_or_default() + accumulated_letters[letter] - quantity);
            }
        }

        for (letter, quantity) in accumulated_letters.iter() {
            if !dict_letters_word.contains_key(letter) {
                cost = Some(cost.unwrap_or_default() + quantity);
            }
        }

        match min_cost {
            Some(c) => Some(min(c, cost.unwrap())),
            None => cost,
        }
    } else {
        min_cost = back_track(
            index + 1,
            magazine,
            accumulated_letters,
            min_cost,
            dict_letters_word,
        );
        let word = magazine[index];
        for letter in word.chars() {
            accumulated_letters
                .entry(letter)
                .and_modify(|e| *e += 1)
                .or_insert(1);
        }
        min_cost = back_track(
            index + 1,
            magazine,
            accumulated_letters,
            min_cost,
            dict_letters_word,
        );
        for letter in word.chars() {
            accumulated_letters.entry(letter).and_modify(|e| *e -= 1);
        }

        min_cost
    }
}

