    for letter in word.chars() {
        dict_letters_word
            .entry(letter)
            .and_modify(|e| *e += 1)
            .or_insert(1);
    }
    let mut accumulated_letters = HashMap::new();

    back_track(
        0,
        magazine,
        &mut accumulated_letters,
        None,
        &dict_letters_word,
    )
}

