use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

pub fn cheapest_connection<'a>(
    flights: &[(&'a str, &'a str)],
    costs: &[usize],
    times: &[usize],
) -> Vec<&'a str> {
    let adj = flights
        .iter()
        .enumerate()
        .fold(HashMap::new(), |mut adj, (i, &(from, _to))| {
            adj.entry(from).or_insert_with(Vec::new).push(i);
            adj
        });

    const SOURCE: &str = "New York";
    const DESTINATION: &str = "Melbourne";

    let mut dist = HashMap::new();
    let mut prev = HashMap::new();
    dist.insert(SOURCE, 0);
    let mut pq = BinaryHeap::new();
    pq.push((Reverse(0), SOURCE));

    while let Some((_, v)) = pq.pop() {
        if v == DESTINATION {
            break;
        }
        if let Some(neighbors) = adj.get(v) {
            for &i in neighbors {
                let (_from, to) = flights[i];
                // To avoid floating point arithmetic, we consider 3 times the true cost:
                // 3*(cost + time/60*100) = 3*cost + 5*time
                // ??? MISSING LINE ???
                let entry = dist.entry(to).or_insert(usize::MAX);
                if alt < *entry {
                    *entry = alt;
                    prev.insert(to, v);
                    pq.push((Reverse(alt), to));
                }
            }
        }
    }

    let mut path = vec![DESTINATION];
    let mut v = DESTINATION;
    while v != SOURCE {
        v = prev[&v];
        path.push(v);
    }
    path.reverse();
    path
}

