fn find_all_elements_in_range(node: &TreeNodePtr, low: i32, high: i32, result: &mut HashSet<i32>) {
    if let Some(node) = node {
        if node.val < low {
            find_all_elements_in_range(&node.right, low, high, result);
        } else if low <= node.val && node.val <= high {
            result.insert(node.val);
            find_all_elements_in_range(&node.left, low, high, result);
            find_all_elements_in_range(&node.right, low, high, result);
        } else {
            find_all_elements_in_range(&node.left, low, high, result);
        }
    }
}

