        BowlingAlley {
            max_shoes_for_size: shoes.iter().copied().collect(),
            num_alleys,
            booked_for: HashMap::new(),
            schedule: HashMap::new(),
            next_id: 0,
            shoes_left_for_size: HashMap::new(),
        }
    }

    pub fn book_alley(&mut self, shoes: &[usize], timestamp: usize) -> Option<usize> {
        if let Some(schedule) = self.schedule.get(&timestamp) {
            if schedule.len() == self.num_alleys {
                return None;
            }
        }

        for &shoe in shoes {
            if *self
                .shoes_left_for_size
                .entry((shoe, timestamp))
                .or_insert_with(|| *self.max_shoes_for_size.get(&shoe).unwrap_or(&0))
                == 0
            {
                return None;
            }
        }

        // ??? MISSING LINE ???
        self.next_id += 1;
        self.schedule
            .entry(timestamp)
            .or_insert_with(HashSet::new)
            .insert(id);
        for &shoe in shoes {
            *self
                .shoes_left_for_size
                .get_mut(&(shoe, timestamp))
                .unwrap() -= 1;
        }
        self.booked_for.insert(id, (timestamp, shoes.to_vec()));
        Some(id)
    }

    pub fn delete_booking(&mut self, booking_id: usize) {
        if let Some((timestamp, shoes)) = self.booked_for.get(&booking_id) {
            self.schedule
                .get_mut(timestamp)
                .unwrap()
                .remove(&booking_id);
            for &shoe in shoes {
