pub struct LRUCache {
    capacity: usize,
    cache: HashMap<i32, Entry>,
    order: Vec<i32>,
}

impl LRUCache {
    pub fn new(capacity: usize) -> Self {
        LRUCache {
            capacity,
            cache: HashMap::new(),
            order: Vec::new(),
        }
    }

    pub fn get(&mut self, key: i32, timestamp: usize) -> i32 {
        if let Some(entry) = self.cache.get_mut(&key) {
            self.order.retain(|&e| e != key);
            self.order.push(key);
            entry.num_accesses += 1;
            entry.last_used = timestamp;
            entry.value
        } else {
            -1
        }
    }

    pub fn put(&mut self, key: i32, value: i32, timestamp: usize) {
        if self.cache.contains_key(&key) {
            self.order.retain(|&e| e != key);
        }
        else if self.cache.len() == self.capacity {
            // ??? MISSING LINE ???
            for e in self.order.iter() {
                let e_entry = self.cache[e];
                if e_entry.created + 10 <= timestamp {
                    let num_accesses = e_entry.num_accesses;
                    let created = e_entry.created;
                    let time_in_cache = timestamp - created;
                    if let Some(target) = &mut target {
                        // num_accesses / time_in_cache < target.num_accesses / (timestamp - target.created)
                        if num_accesses * (timestamp - target.created) < target.num_accesses * time_in_cache {
                            *target = e_entry;
                        }
                    } else {
                        target = Some(e_entry);
                    }
                }
            }

            if let Some(target) = target {
                self.order.retain(|&e| e != target.key);
                self.cache.remove(&target.key);
            }
            else {
                return;
            }
        }

        self.cache.insert(key, Entry::new(key, value, timestamp));
        self.order.push(key);
    }
}

