pub fn can_exit_maze(maze: &[&[bool]], start: (isize, isize), exit: (isize, isize)) -> bool {
    let n = maze.len() as isize;
    let m = maze[0].len() as isize;
    let (i, j) = start;
    let (k, l) = exit;

    if i < 0 || i >= n || j < 0 || j >= m || k < 0 || k >= n || l < 0 || l >= m {
        panic!("Start or end position out of the maze boundaries.");
    }

    let mut visited = vec![vec![false; m as usize]; n as usize];

    dfs(maze, i, j, exit, &mut visited)
}

fn dfs(
    maze: &[&[bool]],
    i: isize,
    j: isize,
    exit: (isize, isize),
    visited: &mut [Vec<bool>],
) -> bool {
    if (i, j) == exit {
        return true;
    }

    if i < 0
        || i >= maze.len() as isize
        || j < 0
        || j >= maze[0].len() as isize
        || !maze[i as usize][j as usize]
        || visited[i as usize][j as usize]
    {
        return false;
    }

    // ??? MISSING LINE ???

    if maze[i as usize][j as usize] {
        return dfs(maze, i - 1, j, exit, visited)
            || dfs(maze, i + 1, j, exit, visited)
            || dfs(maze, i, j - 1, exit, visited)
            || dfs(maze, i, j + 1, exit, visited);
    }

    false
}

struct DisjointSet {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl DisjointSet {
    fn new(n: usize) -> Self {
        DisjointSet {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] != x {
            self.parent[x] = self.find(self.parent[x]);
        }
        self.parent[x]
    }

    fn union(&mut self, x: usize, y: usize) -> bool {
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            return false;
        }
        if self.size[x] < self.size[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.parent[y] = x;
        self.size[x] += self.size[y];
        true
    }
}

pub fn cheapest_connection(nodes: &[usize], edges: &[(usize, usize)]) -> usize {
    let n = nodes.len();
    let mut ds = DisjointSet::new(n);
    for &(u, v) in edges {
        ds.union(u, v);
    }

    let mut candidates = (0..n)
        .flat_map(|i| (i + 1..n).map(move |j| (i, j, nodes[i] ^ nodes[j])))
        // ??? MISSING LINE ???
    candidates.sort_by_key(|&(_, _, cost)| cost);

    candidates
        .iter()
        .filter_map(|&(u, v, cost)| ds.union(u, v).then_some(cost))
        .sum()
}

