pub fn compute_tax_rate(income: i32, tax_brackets: &[(i32, i32)], max_percentage: i32) -> f64 {
    let mut total_tax = 0.;
    let mut previous_threshold = 0;

    for &(threshold, percentage) in tax_brackets {
        if income >= threshold {
            total_tax += (threshold - previous_threshold) as f64 * (percentage as f64 / 100.0);
        } else {
            // ??? MISSING LINE ???
            break;
        }

        previous_threshold = threshold;
    }

    if let Some((last_threshold, _)) = tax_brackets.last() {
        if income > *last_threshold {
            total_tax += (income - last_threshold) as f64 * (max_percentage as f64 / 100.0);
        }
    }

    let tax_rate = (total_tax / income as f64) * 100.;
    (tax_rate * 100.0).round() / 100.0
}

