use std::cmp::min;
use std::collections::HashSet;

fn dfs(
    index: usize,
    candidates: &[i32],
    targets: &[i32],
    curr_list: &mut Vec<i32>,
    curr_products: &mut HashSet<i32>,
    curr_min: i32,
) -> i32 {
    if index == candidates.len() {
        for target in targets {
            if !curr_products.contains(target) {
                return curr_min;
            }
        }
        if curr_min == -1 {
            return curr_list.len() as i32;
        }
        return min(curr_min, curr_list.len() as i32);
    }

    let mut cand_min = dfs(
        index + 1,
        candidates,
        targets,
        curr_list,
        curr_products,
        curr_min,
    );
    curr_list.push(candidates[index]);
    let mut stuff_to_remove = HashSet::new();
    for product in curr_products.iter() {
        // ??? MISSING LINE ???
        if !curr_products.contains(&cand_prod) {
            stuff_to_remove.insert(cand_prod);
        }
    }
    if !curr_products.contains(&candidates[index]) {
        stuff_to_remove.insert(candidates[index]);
    }

    for product in stuff_to_remove.iter() {
        curr_products.insert(*product);
    }
    let cand_min2 = dfs(
        index + 1,
        candidates,
        targets,
        curr_list,
        curr_products,
        curr_min,
    );
    if cand_min == -1 || (cand_min2 != -1 && cand_min2 < cand_min) {
        cand_min = cand_min2;
    }

    for product in stuff_to_remove.iter() {
        curr_products.remove(product);
    }
    curr_list.pop();
    cand_min
}

