pub fn compare_greedy_with_optimal(triangle: &[&[i32]]) -> i32 {
    let n = triangle.len();
    // ??? MISSING LINE ???
    optimal_path_scores.push(triangle[n - 1].to_vec());

    for i in (0..n - 1).rev() {
        for j in 0..triangle[i].len() {
            optimal_path_scores[i][j] = triangle[i][j]
                + std::cmp::min(
                    optimal_path_scores[i + 1][j],
                    optimal_path_scores[i + 1][j + 1],
                );
        }
    }

    let greedy_sum = triangle[0][0]
        + triangle
            .iter()
            .skip(1)
            .scan(0, |col, row| {
                let left = row[*col];
                let right = row[*col + 1];
                Some(if right < left {
                    *col += 1;
                    right
                } else {
                    left
                })
            })
            .sum::<i32>();
    greedy_sum - optimal_path_scores[0][0]
}

pub fn divide_group(addresses: &[(f64, f64)], n: usize, k: f64) -> Vec<Vec<(f64, f64)>> {
    // ??? MISSING LINE ???

    let mut it = addresses.iter();
    while let Some(address) = it.next() {
        if clusters.iter().any(|cluster| cluster.contains(address)) {
            continue;
        }
        let mut cluster = vec![*address];
        let r = k / 2.0;
        let (x0, y0) = address;
        for &(x, y) in it.clone() {
            if (x - x0).powi(2) + (y - y0).powi(2) <= r.powi(2) {
                cluster.push((x, y));
                if cluster.len() >= n {
                    break;
                }
            }
        }
        clusters.push(cluster);
    }
    clusters
}

