    // Sort by number of relationships
    let mut sorted_by_num_rel = persons.to_vec();
    sorted_by_num_rel.sort_by_key(|p| p.num_rels);

    // Calculate median age
    let median_age = if sorted_by_age.len() % 2 == 0 {
        // ??? MISSING LINE ???
        (sorted_by_age[mid - 1].age + sorted_by_age[mid].age) / 2
    } else {
        sorted_by_age[sorted_by_age.len() / 2].age
    };

    // Calculate median number of relationships
    let median_rels = if sorted_by_num_rel.len() % 2 == 0 {
        let mid = sorted_by_num_rel.len() / 2;
        (sorted_by_num_rel[mid - 1].num_rels + sorted_by_num_rel[mid].num_rels) / 2
    } else {
        sorted_by_num_rel[sorted_by_num_rel.len() / 2].num_rels
    };

    persons.iter().filter_map(|p| (p.age == median_age && p.num_rels == median_rels).then_some(p.name.as_str())).collect()
}

