            if i % 2 == 0 {
                -inc
            } else {
                inc
            }
        };
        let h = ((c as i32) + inc) as u8; // this is a safe conversion assuming c is ASCII
        (if h > b'z' {
            b'a' + h - b'z' - 1
        } else if h < b'a' {
