use std::collections::BTreeMap;

pub fn extract_classes_and_methods<'a>(
    java_file_content: &'a str,
) -> BTreeMap<&'a str, Vec<&'a str>> {
    static CLASS_PATTERN: Lazy<Regex> =
        Lazy::new(|| Regex::new(r"\bclass\s+([a-zA-Z0-9_]+)\s*\{").unwrap());
    static METHOD_PATTERN: Lazy<Regex> =
        Lazy::new(|| Regex::new(r"\b([a-zA-Z0-9_]+)\s*\([^)]*\)\s*\{").unwrap());
    const COMPOUND_STATEMENTS_WITH_PARENTHESIZED_EXPRESSION: [&str; 4] =
        ["if", "switch", "while", "for"];

    let mut classes_and_methods = BTreeMap::new();
    let mut current_class = "";

    for line in java_file_content.split("\n") {
        if let Some(captures) = CLASS_PATTERN.captures(line) {
            // ??? MISSING LINE ???
            classes_and_methods.insert(current_class, Vec::new());
            continue;
        }

        if let Some(captures) = METHOD_PATTERN.captures(line) {
            let method_name = captures.get(1).unwrap().as_str();
            if !COMPOUND_STATEMENTS_WITH_PARENTHESIZED_EXPRESSION.contains(&method_name) {
                classes_and_methods
                    .get_mut(current_class)
                    .unwrap()
                    .push(method_name);
            }
        }
    }

    classes_and_methods
}

