pub fn find_furthest_leaves(graph: &[(u32, u32)]) -> ((u32, u32), u32) {
    let mut adj_list = HashMap::<u32, Vec<u32>>::new();
    for &(node1, node2) in graph {
        adj_list.entry(node1).or_default().push(node2);
        adj_list.entry(node2).or_default().push(node1);
    }

    let leaves = adj_list
        .keys()
        .filter(|node| adj_list[node].len() == 1)
        .cloned()
        .collect::<Vec<_>>();

    let mut max_distance = 0;
    let mut furthest_leaves = None;
    for leaf in leaves {
        // ??? MISSING LINE ???
        let mut stack = vec![(leaf, 0)];
        while let Some((node, distance)) = stack.pop() {
            visited.insert(node);
            if node != leaf && adj_list[&node].len() == 1 {
                if distance > max_distance {
                    max_distance = distance;
                    furthest_leaves = Some((leaf, node));
                }
            }
            for neighbor in adj_list[&node].iter() {
                if !visited.contains(neighbor) {
                    stack.push((*neighbor, distance + 1));
                }
            }
        }
    }

    (
        furthest_leaves.expect("graph has at least 2 nodes"),
        max_distance - 1,
    )
}

