fn reverse(mut n: usize, mut n_digits: usize) -> usize {
    let mut reversed_n = 0;
    while n > 0 && n_digits > 0 {
        let last_digit = n % 10;
        n /= 10;
        reversed_n = reversed_n * 10 + last_digit;
        n_digits -= 1;
    }

    reversed_n
}

pub fn find_largest_prime_m(n: usize) -> usize {
    let mut primes = vec![];
    let mut sieve = vec![false; n];
    sieve[0] = true;
    sieve[1] = true;
    let mut i = 2;
    while i < n {
        primes.push(i);
        for j in (i + i..n).step_by(i) {
            sieve[j] = true;
        }
        i += 1;
        while i < n && sieve[i] {
            i += 1;
        }
    }

    let mut power = {
        let mut power = 1;
        // ??? MISSING LINE ???
        while largest_prime > 0 {
            power *= 10;
            largest_prime /= 10;
        }

        power
    };

    let mut minimal_primes = primes
        .into_iter()
        .rev()
        .take_while(|&p| p >= power)
        .collect::<Vec<_>>();

    let mut n_digits = 1;
    while power > 0 && minimal_primes.len() > 1 {
        let first_n_digits = n / power;
        let mut min_diff = n;
        for prime in std::mem::take(&mut minimal_primes) {
            let diff = first_n_digits.abs_diff(reverse(prime, n_digits));
            if diff <= min_diff {
                if diff < min_diff {
                    min_diff = diff;
                    minimal_primes.clear();
                }
                minimal_primes.push(prime);
            }
        }

        power /= 10;
        n_digits += 1;
    }

    minimal_primes[0]
}

